//! Typed UUIDv7 identifiers (`TenantId`, `PrincipalId`, `CalendarId`, ...).
//!
//! Identifiers are opaque, `Copy` newtypes around a [`Uuid`]. They are generated by the `IdGenerator` port
//! (UUIDv7, so database indexes stay roughly ordered by creation time) and are never derived from user input, so
//! the constructors only wrap an existing UUID. The textual form is always the lowercase hyphenated UUID.

use uuid::Uuid;

/// Error returned when text is not a valid identifier of the named kind.
#[derive(Debug, Clone, Copy, PartialEq, Eq, thiserror::Error)]
#[error("invalid {kind} identifier: expected a hyphenated UUID")]
pub struct IdError {
    kind: &'static str,
}

impl IdError {
    /// Creates the error for the named identifier kind (used by the generated `parse` functions).
    pub(crate) const fn new(kind: &'static str) -> Self {
        Self { kind }
    }

    /// The identifier kind that failed to parse, for example `"tenant"`.
    pub const fn kind(&self) -> &'static str {
        self.kind
    }
}

/// Parses exactly the canonical `8-4-4-4-12` hyphenated form (no braces, no `urn:uuid:` prefix, no simple form).
pub(crate) fn parse_hyphenated(input: &str) -> Option<Uuid> {
    if input.len() != 36 {
        return None;
    }
    Uuid::parse_str(input).ok()
}

uuid_id!(
    /// Identifies a tenant.
    TenantId,
    "tenant"
);
uuid_id!(
    /// Identifies a principal (user, group, resource or service).
    PrincipalId,
    "principal"
);
uuid_id!(
    /// Identifies a calendar.
    CalendarId,
    "calendar"
);
uuid_id!(
    /// Identifies a calendar binding (a principal's view of a calendar).
    BindingId,
    "binding"
);
uuid_id!(
    /// Identifies a calendar grant.
    GrantId,
    "grant"
);
uuid_id!(
    /// Identifies a stored calendar object.
    ObjectId,
    "object"
);
uuid_id!(
    /// Identifies a CalendarServer-style notification (invitation, invitation reply).
    NotificationId,
    "notification"
);
uuid_id!(
    /// Identifies a scheduling inbox item.
    InboxItemId,
    "inbox item"
);
uuid_id!(
    /// Identifies an app password.
    CredentialId,
    "credential"
);
uuid_id!(
    /// Identifies an API token, a feed token or an RSVP token.
    TokenId,
    "token"
);
uuid_id!(
    /// Identifies a webhook subscription.
    WebhookId,
    "webhook"
);
uuid_id!(
    /// Identifies a webhook delivery attempt record.
    DeliveryId,
    "delivery"
);
uuid_id!(
    /// Identifies an outbox message.
    OutboxId,
    "outbox"
);
uuid_id!(
    /// Identifies an external (provider) account.
    ExternalAccountId,
    "external account"
);
uuid_id!(
    /// Identifies a domain event (the `id` of the event envelope; also the webhook id).
    EventId,
    "event"
);
uuid_id!(
    /// Identifies one request (`X-Request-Id`), generated when the client sends none.
    RequestId,
    "request"
);

#[cfg(test)]
mod tests {
    use super::*;

    const TEXT: &str = "018f3c1e-7b2a-7c3d-9e4f-0123456789ab";

    #[test]
    fn parse_display_round_trip() {
        let id = TenantId::parse(TEXT).unwrap();
        assert_eq!(id.to_string(), TEXT);
        assert_eq!(TEXT.parse::<TenantId>().unwrap(), id);
        assert_eq!(Uuid::from(id).hyphenated().to_string(), TEXT);
    }

    #[test]
    fn rejects_other_uuid_forms() {
        let uuid = Uuid::parse_str(TEXT).unwrap();
        let bad_inputs: Vec<String> = vec![
            String::new(),
            "not-a-uuid".to_owned(),
            uuid.simple().to_string(),
            uuid.braced().to_string(),
            uuid.urn().to_string(),
            format!("{TEXT} "),
            TEXT.replace('-', "_"),
        ];
        for bad in &bad_inputs {
            assert!(PrincipalId::parse(bad).is_err(), "{bad:?} must be rejected");
        }
        assert_eq!(PrincipalId::parse("x").unwrap_err().kind(), "principal");
    }

    #[test]
    fn upper_case_input_is_accepted_and_normalized() {
        let id = CalendarId::parse(&TEXT.to_uppercase()).unwrap();
        assert_eq!(id.to_string(), TEXT);
    }

    #[test]
    fn serde_is_a_plain_uuid_string() {
        let id = ObjectId::parse(TEXT).unwrap();
        let json = serde_json::to_string(&id).unwrap();
        assert_eq!(json, format!("\"{TEXT}\""));
        assert_eq!(serde_json::from_str::<ObjectId>(&json).unwrap(), id);
        assert!(serde_json::from_str::<ObjectId>("\"nope\"").is_err());
    }

    #[test]
    fn ids_of_different_kinds_do_not_mix() {
        // Compile-time property documented as a runtime check: the same UUID wrapped as two kinds is equal as UUID
        // but the types are distinct, so only `as_uuid` can compare them.
        let uuid = Uuid::parse_str(TEXT).unwrap();
        assert_eq!(
            TenantId::from_uuid(uuid).as_uuid(),
            PrincipalId::from_uuid(uuid).as_uuid()
        );
    }

    #[test]
    fn ids_are_ordered_by_uuid() {
        let a = EventId::parse("018f3c1e-7b2a-7c3d-9e4f-000000000001").unwrap();
        let b = EventId::parse("018f3c1e-7b2a-7c3d-9e4f-000000000002").unwrap();
        assert!(a < b);
    }
}
